(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;};
const names=['Сашин','Наташин','С серой крышей'],panel=$('#rental-battery-panel'),list=$('#rental-battery-list'),status=$('#rental-battery-status'),pageLink=$('#rental-battery-admin-link');
if(!panel||!list)return;
const money=v=>Number.isFinite(v)?new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v):'—';
const when=v=>Number.isFinite(v)?new Date(v).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}):'—';
const num=(v,digits=1,unit='')=>Number.isFinite(v)?Number(v).toLocaleString('ru-RU',{maximumFractionDigits:digits})+unit:'—';
const api=async(path,body)=>{const r=await fetch('/api/admin/'+path,{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Сервер вернул некорректный ответ.');}if(!r.ok)throw Object.assign(Error(d.error||'Не удалось выполнить запрос.'),{status:r.status});return d;};
const states={armed:'Ожидаем сигнал', 'departure-candidate':'Возможен выход',away:'Вероятно на воде','return-candidate':'Возможен возврат',returned:'Возврат сигнала подтверждён',dismissed:'Событие отклонено'};
const cards=new Map(),busy=new Set(),tripAttempts=new Map();let timer=null,loading=false,user=null,rentals=[];
function makeCard(label){const article=el('article');article.className='rental-battery-card';article.dataset.catamaran=label;const head=el('div');head.className='rental-battery-head';const h=el('h3',label),tripBadge=el('span');tripBadge.className='rental-battery-trip-badge';head.append(h,tripBadge);const readings=el('div');readings.className='rental-battery-readings';const deviceLine=el('p');deviceLine.className='rental-battery-device';const trip=el('div');trip.className='rental-battery-trip';const select=el('select');select.setAttribute('aria-label','Оплаченная аренда катамарана для '+label);const arm=el('button','Связать с арендой');arm.type='button';arm.className='rental-battery-action';const armStatus=el('p');armStatus.className='rental-battery-message';const confirmDeparture=el('button','Подтвердить выход');confirmDeparture.type='button';const confirmReturn=el('button','Подтвердить сигнал возврата');confirmReturn.type='button';const dismiss=el('button','Отклонить событие');dismiss.type='button';const tripActions=el('div');tripActions.className='rental-battery-actions';tripActions.append(confirmDeparture,confirmReturn,dismiss);const due=el('p');due.className='rental-battery-due';const explanation=el('p');explanation.className='rental-battery-explanation';trip.append(select,arm,armStatus,tripActions,due,explanation);article.append(head,readings,deviceLine,trip);const view={article,h,tripBadge,readings,deviceLine,select,arm,armStatus,tripActions,confirmDeparture,confirmReturn,dismiss,due,explanation};view.arm.onclick=()=>mutate(label,'arm',null,view);view.confirmDeparture.onclick=()=>{const pending=view.trip?.departurePending===true;const message=pending?'Подтвердить выход и запустить оплаченное время аренды? Будет отмечено фактическое отплытие в списке аренд, затем подтвердится событие BLE. Оплату это не принимает.':'Подтвердить предполагаемый выход по BLE? Это отметит только событие датчика и не изменит аренду или оплату.';if(confirm(message))mutate(label,'confirm-departure',view.trip,view);};view.confirmReturn.onclick=()=>{if(confirm('Подтвердить сигнал вероятного возврата? Это отметит только событие датчика. Аренда останется активной; для закрытия используйте «Вернуть» в списке аренд, где при необходимости отдельно подтвердите доплату.'))mutate(label,'confirm-return',view.trip,view);};view.dismiss.onclick=()=>{const unassign=['armed','away'].includes(view.trip?.state);if(confirm(unassign?'Снять привязку катамарана от аренды? Платёжные данные не изменятся.':'Отклонить это событие датчика? Данные аренды и оплаты не изменятся.'))mutate(label,'dismiss',view.trip,view);};select.addEventListener('change',()=>{view.selectedRental=select.value;});select.addEventListener('blur',()=>{if(view.latestLinkedCounts)updateOptions(view,view.latestNow,view.latestLinkedCounts);});cards.set(label,view);list.append(article);return view;}
function updateOptions(view,now,linkedCounts){view.latestLinkedCounts=linkedCounts;view.latestNow=now;const available=rentals.filter(r=>(linkedCounts.get(r.id)||0)<(Number.isSafeInteger(r.quantity)?r.quantity:1));const signature=available.map(r=>`${r.id}:${r.start}:${r.expectedReturn}:${r.quantity}:${r.clientLabel}`).join('|');if(signature===view.optionSignature&&view.select.options.length)return;const focused=document.activeElement===view.select;if(focused)return;const selected=view.selectedRental||view.select.value;view.select.replaceChildren(el('option','Выберите аренду…'));view.select.options[0].value='';for(const r of available){const option=el('option',`№${r.id} · ${r.clientLabel||'Клиент'} · ${when(r.start)}–${when(r.expectedReturn)} · ${r.quantity} шт.`);option.value=String(r.id);view.select.append(option);}view.optionSignature=signature;const nearest=available.slice().sort((a,b)=>Math.abs((a.start||now)-now)-Math.abs((b.start||now)-now))[0];view.select.value=available.some(r=>String(r.id)===selected)?selected:nearest?String(nearest.id):'';view.selectedRental=view.select.value;view.arm.disabled=!available.length||busy.has(view.article.dataset.catamaran);}
function updateTrip(view,trip){view.trip=trip||null;const candidate=trip?.state==='departure-candidate',returnCandidate=trip?.state==='return-candidate';view.tripBadge.textContent=trip?states[trip.state]||trip.state:'Нет связанной аренды';view.tripBadge.dataset.state=trip?.state||'none';view.dismiss.textContent=['armed','away'].includes(trip?.state)?'Снять привязку':'Отклонить событие';view.arm.hidden=!!trip&&['armed','departure-candidate','away','return-candidate'].includes(trip.state);view.select.hidden=view.arm.hidden;view.tripActions.hidden=!candidate&&!returnCandidate&&!['armed','away'].includes(trip?.state);view.confirmDeparture.hidden=!candidate;view.confirmReturn.hidden=!returnCandidate;view.dismiss.hidden=!trip||!['armed','departure-candidate','away','return-candidate'].includes(trip.state);view.due.hidden=!trip||!Number.isFinite(trip.dueRub);view.due.textContent=Number.isFinite(trip?.dueRub)?`Предварительная доплата по аренде: ${money(trip.dueRub)}${trip.estimated?' · оценка по тарифу':''}${Number.isFinite(trip.rentalQuantity)&&trip.rentalQuantity>1?` · за аренду целиком (${trip.rentalQuantity} катамарана)`:''}`:'';if(trip?.estimated&&Number.isFinite(trip.quoteMinutes)&&trip.quoteMinutes>0)view.due.textContent+=` · опоздание округлено до ${trip.quoteMinutes} мин`;if(Number.isFinite(trip?.existingDueRub)&&trip.existingDueRub>0)view.due.textContent+=` · уже начислено ${money(trip.existingDueRub)}`;if(Number.isFinite(trip?.overtimeQuoteRub)&&trip.overtimeQuoteRub>0)view.due.textContent+=` · ориентир за опоздание ${money(trip.overtimeQuoteRub)}`;view.explanation.textContent=trip?.state==='return-candidate'?'Если нужно начислить доплату за опоздание, сначала оформите продление +30/+60 минут в аренде, затем нажмите «Вернуть» и подтвердите оплату. Подтверждение сигнала здесь не принимает деньги.':trip?.state==='departure-candidate'?(trip.departurePending?'Подтверждение отметит фактическое отплытие через действующее действие проката и запустит оплаченное время, затем подтвердит сигнал BLE. Новых списаний не будет.':'Подтверждение фиксирует только событие BLE; сведения об аренде и оплате не меняются.') : '';if(trip){const eventTime=trip.detectedReturnAt||trip.detectedDepartureAt;view.armStatus.textContent=`Аренда №${trip.rentalId} · ${trip.clientLabel||'Клиент'} · ${when(trip.start)}–${when(trip.expectedReturn)}${eventTime?' · сигнал '+when(eventTime):''}`;}else view.armStatus.textContent='';}
function render(data){rentals=Array.isArray(data.rentals)?data.rentals:[];const boats=new Map((data.catamarans||[]).map(x=>[x.label,x]));for(const label of names)if(!cards.has(label))makeCard(label);for(const boat of data.catamarans||[])if(boat.label&&!cards.has(boat.label))makeCard(boat.label);const linkedIds=new Map();for(const trip of (data.catamarans||[]).map(x=>x.trip).filter(t=>t&&['armed','departure-candidate','away','return-candidate'].includes(t.state)))linkedIds.set(trip.rentalId,(linkedIds.get(trip.rentalId)||0)+1);for(const [label,view] of cards){const boat=boats.get(label),devices=Array.isArray(boat?.devices)?boat.devices:[];view.article.dataset.state=devices.some(d=>d.online===true&&d.stale!==true)?'fresh':devices.some(d=>d.online===false||d.stale===true)?'stale':'unknown';view.article.hidden=!boat;view.readings.replaceChildren();for(const device of devices){const row=el('div');row.className='rental-battery-reading';row.dataset.freshness=device.online===false?'offline':device.stale===true?'stale':device.online===true?'fresh':'unknown';const heading=el('strong',device.name||'Аккумулятор');const soc=el('b',num(device.socPercent,1,'%'));soc.className='rental-battery-soc';soc.dataset.charge=Number.isFinite(device.socPercent)?device.socPercent>=50?'high':device.socPercent>=20?'medium':'low':'unknown';const metrics=el('span',`Напряжение ${num(device.voltageV,2,' В')} · Температура ${num(device.temperatureC,1,' °C')}`);const state=el('small',`ESP32 ${device.online===true?'на связи':device.online===false?'не в сети':'—'} · BMS ${device.bmsConnected===true?'на связи':device.bmsConnected===false?'нет связи':'—'} · измерено ${when(device.lastMeasuredAt)}`);row.append(heading,soc,metrics,state);view.readings.append(row);}if(!devices.length){const noDevice=el('p','Нет привязанного аккумулятора.');noDevice.className='rental-battery-no-device';view.readings.append(noDevice);}view.deviceLine.textContent=devices.length>1?`${devices.length} отдельных аккумулятора · заряд не усредняется`:'';updateTrip(view,boat?.trip||null);updateOptions(view,data.now||Date.now(),linkedIds);}status.textContent='Данные обновлены в '+new Date(data.now||Date.now()).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'});}
async function markRentalDeparture(trip,attempt,view){if(attempt.rentalDepartureDone)return;const body=attempt.rentalDepartureBody||(attempt.rentalDepartureBody={id:trip.rentalId,revision:trip.rentalRevision});try{await api('rental-depart',body);attempt.rentalDepartureDone=true;return;}catch(error){if(error.status===409||!error.status||error.status>=500){await refresh();if(view.trip?.id===trip.id&&view.trip.departurePending===false){attempt.rentalDepartureDone=true;return;}}throw error;}}
async function mutate(label,action,trip,view){if(busy.has(label))return;const key=`${label}:${action}:${trip?.id||view.select.value||'new'}`;let attempt=tripAttempts.get(key);if(!attempt){let tripBody;if(action==='arm'){const rentalId=Number(view.select.value);if(!Number.isSafeInteger(rentalId)||rentalId<1){view.armStatus.textContent='Выберите конкретную аренду.';return;}tripBody={action,label,rentalId,requestId:crypto.randomUUID()};}else{if(!trip)return;tripBody={action,tripId:trip.id,revision:trip.revision,requestId:crypto.randomUUID()};}attempt={tripBody,rentalDepartureBody:null,rentalDepartureDone:false};tripAttempts.set(key,attempt);}busy.add(label);view.arm.disabled=true;for(const b of [view.confirmDeparture,view.confirmReturn,view.dismiss])b.disabled=true;view.armStatus.textContent=action==='confirm-departure'&&trip?.departurePending?'Отмечаем отплытие в списке аренд…':'Сохраняем отметку…';try{if(action==='confirm-departure'&&trip?.departurePending&&!attempt.rentalDepartureDone){await markRentalDeparture(trip,attempt,view);view.armStatus.textContent='Отплытие отмечено. Подтверждаем событие датчика…';}await api('battery-trips',attempt.tripBody);tripAttempts.delete(key);await refresh();if(action==='confirm-departure'&&attempt.rentalDepartureDone)view.armStatus.textContent='Отплытие отмечено. Список аренд обновится при следующем обновлении.';}catch(error){if(error.status&&error.status<500)tripAttempts.delete(key);if(attempt.rentalDepartureDone)await refresh();view.armStatus.textContent=error.message||'Не удалось сохранить отметку.';if(attempt.rentalDepartureDone)view.armStatus.textContent='Отплытие отмечено, но подтверждение события датчика не завершено. '+view.armStatus.textContent;if(!error.status||error.status>=500)view.armStatus.textContent+=' Ответ не подтверждён; повторите действие безопасно.';}finally{busy.delete(label);view.arm.disabled=!view.select.value;for(const b of [view.confirmDeparture,view.confirmReturn,view.dismiss])b.disabled=false;}}
async function refresh(){if(loading||document.hidden||!user)return;loading=true;try{render(await api('battery-overview'));panel.hidden=false;}catch(error){panel.hidden=false;status.textContent='Связь с сервером не подтверждена; ниже могут отображаться последние полученные показания. '+(error.status===403?'Доступ ограничен ролями сотрудника и администратора.':error.message||'Не удалось обновить данные.');for(const view of cards.values()){view.article.dataset.state='unknown';for(const row of view.readings.children)row.dataset.freshness='unknown';view.armStatus.textContent='Связь с сервером не подтверждена.';}}finally{loading=false;}}
function stop(){if(timer){clearInterval(timer);timer=null;}}function start(){stop();if(!document.hidden&&user)timer=setInterval(refresh,15000);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else{refresh();start();}});
(async()=>{try{const session=await api('session');user=session.user;if(!user||!['admin','staff'].includes(user.role)||user.scheduleOnly){panel.hidden=true;return;}pageLink.hidden=user.role!=='admin';await refresh();start();}catch(error){panel.hidden=true;}})();
})();
